#!/usr/bin/env bash
# Tests 2026-11-15_catchtrace_link.sql on a LOCAL throwaway database that copies
# the parts of the live shop database it touches (definitions read from the live
# database on 15 Nov 2026). Never point this at the live database.
set -uo pipefail
cd "$(dirname "$0")"
export PGHOST=${PGHOST:-127.0.0.1} PGPORT=${PGPORT:-54329} PGUSER=${PGUSER:-postgres}
DB=mfm_link_test
psql -X -q -d postgres -c "drop database if exists $DB" -c "create database $DB" >/dev/null
psql -X -q -v ON_ERROR_STOP=1 -d $DB <<'SQL' >/dev/null
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
end $$;
create schema auth;
create table auth.users (id uuid primary key);
create function auth.uid() returns uuid language sql stable as $f$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $f$;
grant usage on schema auth to anon, authenticated; grant execute on function auth.uid() to anon, authenticated;
-- copies of the live definitions
create table public.app_actor (user_id uuid primary key references auth.users (id) on delete cascade, display_name text,
  domains text[] not null default '{}', roles text[] not null default '{customer}', active boolean not null default true,
  note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), updated_by uuid);
create table public.mfm_shop_products (id bigint generated by default as identity primary key, name text, sw_name text, price numeric, sale_unit text,
  catch_weight boolean, stock_qty numeric, in_stock boolean, sort_order smallint, active boolean, updated_at timestamptz, cost numeric);
create table public.mfm_shop_intake (id bigint generated by default as identity primary key, product_id bigint references public.mfm_shop_products (id),
  qty_added numeric not null, staff_name text, created_at timestamptz default now(), change_type text default 'intake', reason text);
alter table public.app_actor enable row level security; alter table public.mfm_shop_products enable row level security; alter table public.mfm_shop_intake enable row level security;
create policy p_read on public.mfm_shop_products for select to authenticated using (true);
grant select on public.mfm_shop_products to authenticated;
CREATE OR REPLACE FUNCTION public.mfm_is_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$
  select exists (select 1 from public.app_actor where user_id = auth.uid() and active and roles && array['owner','super_admin']::text[]); $function$;
CREATE OR REPLACE FUNCTION public.add_shop_stock(p_product bigint, p_qty numeric, p_staff text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
begin
  if not public.mfm_is_owner() then raise exception 'owner only — adding stock is restricted to the owner'; end if;
  update public.mfm_shop_products set stock_qty = coalesce(stock_qty,0) + p_qty, in_stock = true, updated_at = now() where id = p_product;
  insert into public.mfm_shop_intake (product_id, qty_added, staff_name, change_type) values (p_product, p_qty, p_staff, 'intake');
end $function$;
-- Supabase's default: new functions and tables are open to anon and authenticated unless revoked
alter default privileges in schema public grant all on tables to anon, authenticated;
alter default privileges in schema public grant execute on functions to anon, authenticated;
insert into auth.users values ('00000000-0000-0000-0000-00000000000a'), ('00000000-0000-0000-0000-00000000000b');
insert into public.app_actor (user_id, roles) values ('00000000-0000-0000-0000-00000000000a', '{owner}'), ('00000000-0000-0000-0000-00000000000b', '{staff}');
insert into public.mfm_shop_products (name, sw_name, price, sale_unit, catch_weight, stock_qty, in_stock, active) values
  ('TEST Rabbitfish', 'Tafi', 900, 'kg', true, 10, true, true), ('TEST Octopus', 'Pweza', 1200, 'kg', true, 0, false, true);
insert into public.mfm_shop_intake (product_id, qty_added, staff_name, change_type) values (1, 10, 'owner', 'intake'), (1, -1, 'owner', 'correction');
SQL
psql -X -q -v ON_ERROR_STOP=1 -d $DB -f 2026-11-15_catchtrace_link.sql >/dev/null || { echo "not ok - migration failed"; exit 1; }
psql -X -q -v ON_ERROR_STOP=1 -d $DB -c "CREATE OR REPLACE FUNCTION public.mfm_is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS \$f\$ select exists (select 1 from public.app_actor where user_id = auth.uid() and active and roles && array['staff','dispatch','inventory','finance','owner','super_admin']::text[]) \$f\$" >/dev/null
psql -X -q -v ON_ERROR_STOP=1 -d $DB -f 2026-11-15b_counter_traced.sql >/dev/null || { echo "not ok - counter migration failed"; exit 1; }

pass=0; fail=0
t() { if [ "$2" = "$3" ]; then pass=$((pass+1)); echo "ok - $1"; else fail=$((fail+1)); echo "not ok - $1 (got '$2', expected '$3')"; fi; }
as() { # as <uid|anon> <sql>
  local who=$1; shift
  if [ "$who" = anon ]; then psql -X -q -A -t -d $DB -c "set role anon; $*" 2>&1 | grep -v '^CONTEXT\|^PL/pgSQL\|^LINE\|^ *\^'
  else psql -X -q -A -t -d $DB -c "set request.jwt.claim.sub = '$who'; set role authenticated; $*" 2>&1 | grep -v '^CONTEXT\|^PL/pgSQL\|^LINE\|^ *\^'; fi
}
OWN=00000000-0000-0000-0000-00000000000a; STF=00000000-0000-0000-0000-00000000000b
TOK=0123456789abcdef0123456789abcdef
SUM='{"species":["Rabbitfish"],"landing_sites":["Shimoni"],"verified":"community"}'
call() { as "$1" "select public.add_shop_stock_traced(1, $2, 'owner', '$3', 'staging', 'BAT-1', '$SUM', false)"; }

r=$(call $OWN 4.5 $TOK)
t "the owner receives traced stock" "$(echo "$r" | grep -c intake_id)" 1
t "... stock goes up by the amount received" "$(psql -X -A -t -d $DB -c 'select stock_qty from public.mfm_shop_products where id = 1')" 14.5
t "... one ordinary intake row is written, with the batch as reason" "$(psql -X -A -t -d $DB -c "select change_type || '|' || qty_added || '|' || reason from public.mfm_shop_intake order by id desc limit 1")" "intake|4.5|CatchTrace BAT-1"
t "... and one link row ties it to the QR code" "$(psql -X -A -t -d $DB -c "select count(*) || '|' || max(trace_token) || '|' || max(summary->>'verified') from public.mfm_shop_trace_links")" "1|$TOK|community"
t "... the first use of a code reports nothing received on it before" "$(echo "$r" | grep -o '"earlier_qty_on_this_code": [0-9.]*')" '"earlier_qty_on_this_code": 0'
r2=$(call $OWN 2 $TOK)
t "the same code entered again reports what was already received on it" "$(echo "$r2" | grep -o '"earlier_qty_on_this_code": [0-9.]*')" '"earlier_qty_on_this_code": 4.5'
t "shop_trace_code_used gives the total on a code" "$(as $OWN "select (public.shop_trace_code_used('$TOK'))->>'qty'")" 6.5
t "staff cannot add traced stock" "$(call $STF 1 $TOK | grep -c 'owner only')" 1
t "signed-out callers cannot run it at all" "$(call anon 1 $TOK | grep -c 'permission denied')" 1
t "a malformed code is refused" "$(call $OWN 1 'not-a-code' | grep -c 'not a CatchTrace QR code')" 1
t "zero or negative amounts are refused" "$(call $OWN 0 $TOK | grep -c 'above zero')" 1
t "nothing changed after the refusals" "$(psql -X -A -t -d $DB -c 'select stock_qty from public.mfm_shop_products where id = 1')" 16.5
t "a refused call leaves no half-written rows" "$(psql -X -A -t -d $DB -c "select (select count(*) from public.mfm_shop_intake) || '|' || (select count(*) from public.mfm_shop_trace_links)")" "4|2"
psql -X -q -d $DB -c "alter table public.mfm_shop_trace_links add constraint test_fail check (qty < 100)" >/dev/null
call $OWN 500 $TOK >/dev/null
t "if the link cannot be written, the stock is not added either (one transaction)" "$(psql -X -A -t -d $DB -c 'select stock_qty from public.mfm_shop_products where id = 1')" 16.5
psql -X -q -d $DB -c "alter table public.mfm_shop_trace_links drop constraint test_fail" >/dev/null
t "the plain add_shop_stock still works unchanged" "$(as $OWN "select public.add_shop_stock(2, 3, 'owner')" >/dev/null; psql -X -A -t -d $DB -c 'select stock_qty from public.mfm_shop_products where id = 2')" 3
t "recent traced intakes list both, newest first" "$(as $OWN "select string_agg(qty::text, ',') from public.shop_trace_links_recent(30)")" "2,4.5"
t "coverage: received counts intakes only (not corrections); staging links count as test, not as traced" \
  "$(as $OWN "select received || '|' || traced || '|' || traced_test from public.shop_trace_coverage(30) where product_id = 1")" "16.5|0|6.5"
t "staff cannot read the traced list" "$(as $STF "select count(*) from public.shop_trace_links_recent(30)" | grep -c 'owner only')" 1
t "staff cannot read the link table directly" "$(as $STF "select count(*) from public.mfm_shop_trace_links" | grep -c 'permission denied')" 1
t "signed-out callers cannot read the link table" "$(as anon "select count(*) from public.mfm_shop_trace_links" | grep -c 'permission denied')" 1
# ---- counter: traced right now
t "the counter sees product 1 as traced now (latest intake has a code)" "$(as $STF "select string_agg(product_id || ':' || batch_ref, ',') from public.shop_traced_now()")" "1:BAT-1"
t "... it returns the fish and landing site, nothing about quantities or prices" "$(as $STF "select (species->>0) || '|' || (landing_sites->>0) from public.shop_traced_now()")" "Rabbitfish|Shimoni"
as $OWN "select public.add_shop_stock(1, 1, 'owner')" >/dev/null
t "after an untraced delivery, the product is no longer shown as traced" "$(as $STF "select count(*) from public.shop_traced_now()")" 0
call $OWN 1 $TOK >/dev/null
psql -X -q -d $DB -c "update public.mfm_shop_products set stock_qty = 0 where id = 1" >/dev/null
t "a sold-out product is not shown as traced" "$(as $STF "select count(*) from public.shop_traced_now()")" 0
psql -X -q -d $DB -c "update public.mfm_shop_products set stock_qty = 5 where id = 1; update public.mfm_shop_trace_links set created_at = now() - interval '30 days'" >/dev/null
t "a code received more than 21 days ago no longer counts" "$(as $STF "select count(*) from public.shop_traced_now()")" 0
t "customers (no staff role) cannot read it" "$(psql -X -q -A -t -d $DB -c "insert into auth.users values ('00000000-0000-0000-0000-00000000000c'); insert into public.app_actor (user_id, roles) values ('00000000-0000-0000-0000-00000000000c', '{customer}')" >/dev/null; as 00000000-0000-0000-0000-00000000000c "select count(*) from public.shop_traced_now()" | grep -c 'not staff')" 1
t "signed-out callers cannot read it" "$(as anon "select count(*) from public.shop_traced_now()" | grep -c 'permission denied')" 1
psql -X -q -d postgres -c "drop database if exists $DB" >/dev/null
echo "# $pass passed, $fail failed"; [ $fail = 0 ]
